#include <Arduino.h>
#include <WiFi.h>

String commandLine = "";
const char* OS_NAME = "GLASER OS";
const char* OS_VERSION = "1.0";

void showHelp() {
  Serial.println("\n--- GLASER OS COMMANDS ---");
  Serial.println("help     - Show commands");
  Serial.println("version  - OS version");
  Serial.println("sysinfo  - ESP32 hardware info");
  Serial.println("uptime   - Time since startup");
  Serial.println("heap     - Free RAM");
  Serial.println("wifi     - Wi-Fi connection status");
  Serial.println("ip       - Network IP address");
  Serial.println("echo TXT - Print text");
  Serial.println("clear    - Clear terminal output");
  Serial.println("reboot   - Restart ESP32");
}

void runCommand(String cmd) {
  cmd.trim();

  if (cmd == "help") {
    showHelp();
  } else if (cmd == "version") {
    Serial.printf("%s v%s\n", OS_NAME, OS_VERSION);
  } else if (cmd == "sysinfo") {
    Serial.printf("Chip: ESP32\nCPU: %u MHz\nFlash: %u bytes\n",
                  ESP.getCpuFreqMHz(), ESP.getFlashChipSize());
    Serial.printf("Chip revision: %u\n", ESP.getChipRevision());
  } else if (cmd == "uptime") {
    Serial.printf("%lu seconds\n", millis() / 1000UL);
  } else if (cmd == "heap") {
    Serial.printf("Free RAM: %u bytes\n", ESP.getFreeHeap());
    Serial.printf("Largest free block: %u bytes\n",
                  ESP.getMaxAllocHeap());
  } else if (cmd == "wifi") {
    if (WiFi.status() == WL_CONNECTED) {
      Serial.println("Connected to Wi-Fi");
      Serial.print("IP: ");
      Serial.println(WiFi.localIP());
    } else {
      Serial.println("Not connected to Wi-Fi");
      Serial.println("Wi-Fi credentials may need configuring.");
    }
  } else if (cmd == "ip") {
    Serial.println(WiFi.localIP());
  } else if (cmd.startsWith("echo ")) {
    Serial.println(cmd.substring(5));
  } else if (cmd == "clear") {
    for (int i = 0; i < 35; i++) Serial.println();
  } else if (cmd == "reboot") {
    Serial.println("Restarting GLASER OS...");
    delay(500);
    ESP.restart();
  } else if (cmd.length() > 0) {
    Serial.println("Unknown command. Type help.");
  }

  Serial.print("glaser@cyd:~$ ");
}

void setup() {
  Serial.begin(115200);
  delay(1000);

  Serial.println("\n");
  Serial.println("==============================");
  Serial.println("        GLASER OS");
  Serial.println("   ESP32 Embedded Terminal");
  Serial.println("==============================");
  Serial.println("Welcome.");
  Serial.println("This is an embedded command shell,");
  Serial.println("not a full Linux operating system.");
  showHelp();
  Serial.print("\nglaser@cyd:~$ ");
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();

    if (c == '\r') continue;

    if (c == '\n') {
      Serial.println();
      runCommand(commandLine);
      commandLine = "";
    } else if (c == 8 || c == 127) {
      if (commandLine.length() > 0) {
        commandLine.remove(commandLine.length() - 1);
        Serial.print("\b \b");
      }
    } else if (c >= 32 && c <= 126 &&
               commandLine.length() < 120) {
      commandLine += c;
      Serial.write(c);
    }
  }
}
